/* Type C page setup (one time, before the first Type C ship). Source of truth: tools/typec/typec.css.
   Chosen by Jonathan 2026-09-29: accent-bar serif section headers; compact illness script (iPhone: option B stacked
   with a color bar per disease; iPad and desktop: side-by-side table); dense row cards; first steps grouped. */
nav.jump{display:flex;flex-wrap:wrap;gap:6px;margin:4px 0 16px}
nav.jump a{font:600 12px/1 var(--sans,system-ui);padding:7px 10px;border-radius:999px;background:#E3EEE5;color:#1E4A28;text-decoration:none}
h5.tsec{font-family:var(--serif);font-size:20px;font-weight:600;text-transform:none;letter-spacing:-.15px;color:var(--ink);line-height:1.2;margin:32px 0 10px;padding:1px 0 1px 11px;border:none;border-left:3px solid var(--accent);scroll-margin-top:12px}
.chainblk{margin:12px 0 4px;font-size:14.5px;line-height:1.45}.chainblk p{margin:2px 0}.chainblk p.ar{padding-left:18px}
.chainblk .lbl{display:block;margin-bottom:6px}
.crit.fu{margin-top:12px}
.traps > .lbl{display:block;grid-column:1/-1;margin-bottom:6px}
dl.rows.mnem dt b.mn{color:var(--criteria,#0a5461);font-size:1.25em;font-weight:800;letter-spacing:.02em}

/* ---- Type C layout pilot: compact illness script and dense row cards ---- */
.scriptcard{background:linear-gradient(145deg,#F4F5F5 0%,#EEF0F0 55%,#E9EBEB 100%);border-radius:var(--r-sub);box-shadow:var(--e2);padding:4px 16px 12px;margin:0 0 20px}
.scriptcard .tw{background:none;box-shadow:none;padding:0;margin:0;overflow:visible}
.scriptcard caption{padding:12px 0 4px}
table.script thead{display:none}
table.script tbody tr{background:none!important}
table.script tbody td{padding:8px 0;border-top:1px solid var(--hair);font-size:15px;line-height:1.45}
table.script tbody tr:first-child td{border-top:none}
table.script tbody td:first-child{width:96px;padding-right:12px;font-family:var(--sans);font-size:10.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);padding-top:11px}
.scriptcard .chainblk{margin:10px 0 0;padding-top:12px;border-top:1px solid var(--hair)}
@media (min-width:900px){
  .scriptcard:not(.multi){display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);column-gap:26px;align-items:start}
  .scriptcard:not(.multi) .chainblk{margin:14px 0 0;padding:0 0 0 22px;border-top:none;border-left:1px solid var(--hair)}
}
@media (max-width:640px){
  .scriptcard{padding:2px 14px 12px;border-radius:14px}
  .tw table.script tbody tr{display:grid;grid-template-columns:5.4em minmax(0,1fr);column-gap:10px;background:none!important;box-shadow:none;border-radius:0;margin:0;padding:9px 0}
  .tw table.script tbody tr+tr{border-top:1px solid var(--hair)}
  .tw table.script tbody td{padding:0;border:none;font-size:14.4px;line-height:1.45}
  .tw table.script tbody td:first-child{font-family:var(--sans);font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:3px 0 0;margin:0;border:none;width:auto}
  .tw table.script tbody td:not(:first-child)::before{content:none}
  /* dense row cards: title line carries the order pill; labels sit inline */
  .tw table.dense tbody tr{display:flex;flex-wrap:wrap;align-items:baseline;column-gap:8px;padding:11px 14px 9px;margin:0 0 8px}
  .tw table.dense tbody td{width:auto;max-width:100%;flex:1 1 100%;padding:3px 0;font-size:14.2px;line-height:1.45;order:2}
  .tw table.dense tbody td:first-child{flex:1 1 60%;min-width:0;order:0;font-size:16px;padding:0 0 4px;margin:0;border-bottom:none}
  .tw table.dense tbody td:not(:first-child)::before{display:inline;margin-right:7px;font-size:9.5px;letter-spacing:.09em;vertical-align:1px}
  .tw table.dense tbody td[data-label="Order"]{flex:0 0 auto;width:auto;order:1;align-self:flex-start;padding:2px 9px;margin:0 0 3px;border-radius:999px;background:var(--accent-bg);color:var(--accent);font-size:10.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase}
  .tw table.dense tbody td[data-label="Order"]::before{content:none}
}

/* mnemonic block: room for long terms, and space before the next table */
dl.rows.mnem{margin-bottom:22px}
@media (max-width:640px){ dl.rows.mnem{grid-template-columns:minmax(0,9.5em) minmax(0,1fr)} }

/* multi-entity script (2 or 3 diseases side by side) */
table.script.multi{table-layout:fixed}
table.script.multi thead{display:table-header-group}
table.script.multi thead th:first-child{width:96px}
table.script.multi thead th{padding:10px 12px 6px 0}
table.script.multi tbody td:not(:first-child){padding-right:14px}
.scriptcard .chainblk .lbl{font-family:var(--sans);font-size:10.5px;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}
@media (max-width:640px){
  .tw table.script.multi thead{display:none}
  .tw table.script.multi tbody tr{grid-template-columns:minmax(0,1fr);row-gap:3px}
  .tw table.script.multi tbody td:first-child{padding:0 0 1px}
  .tw table.script.multi tbody td:not(:first-child)::before{content:attr(data-label) ": ";display:inline;font-family:var(--sans);font-size:inherit;font-weight:700;letter-spacing:0;text-transform:none;color:var(--ink);margin:0}
}

/* ---- first steps done together: one shaded, outlined group ---- */
table tbody.first td{background:rgba(84,74,196,.06)}
table tbody.first tr td:first-child{box-shadow:inset 3px 0 0 var(--accent)}
table tbody.first tr:first-child td{border-top:1.5px solid rgba(84,74,196,.35)}
table tbody.first tr:last-child td{border-bottom:1.5px solid rgba(84,74,196,.35)}
table tbody.first tr:not(:first-child):not(:has(>td:first-child:empty)) td{border-top:1px dashed rgba(84,74,196,.35)}
table:has(tbody.first) caption::after{content:"Shaded rows: first steps, done together, in either order";display:block;font-family:var(--sans);font-size:10px;letter-spacing:.08em;text-transform:uppercase;font-weight:700;color:var(--accent);margin-top:4px}
@media (max-width:640px){
  table:has(tbody.first) caption::after{content:none}
  .tw table.dense tbody.first{display:block;background:linear-gradient(145deg,#F2F1FA 0%,#EDECF7 60%,#E9E8F4 100%);border-radius:14px;box-shadow:var(--e2),inset 0 0 0 1.5px rgba(84,74,196,.32);margin:0 0 12px;padding:0 0 2px}
  .tw table.dense tbody.first::before{content:"Do first \00b7  together, in either order";display:block;padding:11px 14px 3px;font-size:10px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}
  .tw table.dense tbody.first tr{background:none!important;box-shadow:none!important;border-radius:0;margin:0;position:relative}
  .tw table.dense tbody.first td{background:none;border:none!important;box-shadow:none!important}
  .tw table.dense tbody.first td[data-label="Order"]{display:none}
  .tw table.dense tbody.first tr:not(:first-child):not(:has(>td:first-child:empty)){border-top:1.5px dashed rgba(84,74,196,.35);margin-top:14px;padding-top:16px}
  .tw table.dense tbody.first tr:not(:first-child):not(:has(>td:first-child:empty))::before{content:"+";position:absolute;top:-13px;left:50%;transform:translateX(-50%);width:24px;height:24px;border-radius:50%;background:#F7F6FD;color:var(--accent);font:800 16px/24px var(--sans);text-align:center;box-shadow:0 0 0 1.5px rgba(84,74,196,.35)}
  /* outcome rows of one test (empty first cell) sit under it as branches */
  .tw table.dense tbody.first tr:has(>td:first-child:empty){padding-top:0}
  .tw table.dense tbody.first tr:has(+tr>td:first-child:empty){padding-bottom:2px}
  .tw table.dense tbody td:first-child:empty{display:none}
  .tw table.dense tbody.first tr:has(>td:first-child:empty) td[data-label="Result"]::before,
  .tw table.dense tbody.first tr:has(+tr>td:first-child:empty) td[data-label="Result"]::before{content:none}
  .tw table.dense tbody.first tr:has(>td:first-child:empty) td[data-label="Result"],.tw table.dense tbody.first tr:has(+tr>td:first-child:empty) td[data-label="Result"]{flex:0 0 7.4em;padding:3px 0}
  .tw table.dense tbody.first tr:has(>td:first-child:empty) td[data-label="What it points to"],.tw table.dense tbody.first tr:has(+tr>td:first-child:empty) td[data-label="What it points to"]{flex:1 1 0;min-width:0;padding:3px 0}
  .tw table.dense tbody.first tr:has(>td:first-child:empty){flex-wrap:nowrap}
  .tw table.dense tbody.first tr:has(+tr>td:first-child:empty) td:first-child{flex:1 1 100%}
  .tw table.dense tbody.first tr:has(>td:first-child:empty) td[data-label="What it points to"]::before,
  .tw table.dense tbody.first tr:has(+tr>td:first-child:empty) td[data-label="What it points to"]::before{content:"\2192";letter-spacing:0;font-size:14px;color:var(--faint);margin-right:6px}
}

/* H3: stacked, each disease a colored bar, names once in a legend */
@media (max-width:640px){
  .tw table.script.multi thead{display:block;position:static;width:auto;height:auto;clip:auto;overflow:visible;white-space:normal;margin:4px 0 2px}
  .tw table.script.multi thead tr{display:flex;gap:14px;padding:6px 0;border-bottom:1.5px solid var(--hair)}
  .tw table.script.multi thead th{display:block;padding:0 0 0 9px;font-size:11px;letter-spacing:.06em;color:var(--ink);font-weight:800}
  .tw table.script.multi thead th:first-child{display:none}
  .tw table.script.multi thead th:nth-child(2){box-shadow:inset 3px 0 0 var(--accent)} .tw table.script.multi thead th:nth-child(3){box-shadow:inset 3px 0 0 var(--criteria)} .tw table.script.multi thead th:nth-child(4){box-shadow:inset 3px 0 0 var(--board)}
  .tw table.script.multi tbody td:not(:first-child)::before{content:none}
  .tw table.script.multi tbody td:not(:first-child){padding:1px 0 1px 10px}
  .tw table.script.multi tbody td:nth-child(2){box-shadow:inset 3px 0 0 var(--accent)}
  .tw table.script.multi tbody td:nth-child(3){box-shadow:inset 3px 0 0 var(--criteria)}
  .tw table.script.multi tbody td:nth-child(4){box-shadow:inset 3px 0 0 var(--board)}
}
